"use client";

// The brewing schedule: a catalogue of every pack with its photo and its
// recommended and minimum timing. Reads the same generated catalog as the planners, so it is as current
// as the last catalog update and nobody has to maintain it by hand.
//
// "Download PDF" and "Download CSV" are real files regenerated by the catalog
// workflows (scripts/export-schedule.ts), for people who never open the app.

import { useMemo, useState } from "react";

import Image from "next/image";

import PackThumb from "@/components/PackThumb";
import PinterNotice from "@/components/PinterNotice";
import SiteNav from "@/components/SiteNav";
import { scheduleRows as rows, type ScheduleStatus as Status } from "@/lib/scheduleRows";

type Filter = "current" | "all" | "gone";
type Sort = "name" | "total" | "abv";

const FILTERS: { id: Filter; label: string; test: (s: Status) => boolean }[] = [
  { id: "current", label: "On sale", test: (s) => s === "available" },
  { id: "all", label: "All", test: () => true },
  { id: "gone", label: "Discontinued / unavailable", test: (s) => s !== "available" },
];

const SORTS: { id: Sort; label: string }[] = [
  { id: "name", label: "Name" },
  { id: "total", label: "Total days" },
  { id: "abv", label: "ABV" },
];

export default function SchedulePage() {
  const [filter, setFilter] = useState<Filter>("current");
  const [sort, setSort] = useState<Sort>("name");
  const [query, setQuery] = useState("");

  const shown = useMemo(() => {
    const test = FILTERS.find((f) => f.id === filter)!.test;
    const words = query.toLowerCase().split(/\s+/).filter(Boolean);
    return rows
      .filter((r) => test(r.status))
      .filter((r) => words.every((w) => `${r.name} ${r.style}`.toLowerCase().includes(w)))
      .sort((a, b) =>
        sort === "name"
          ? a.name.localeCompare(b.name)
          : sort === "total"
            ? a.totalDays - b.totalDays || a.name.localeCompare(b.name)
            : b.abv - a.abv || a.name.localeCompare(b.name),
      );
  }, [filter, sort, query]);

  const chip = (active: boolean) =>
    `rounded-xl px-3 py-2 text-sm font-semibold transition focus:outline-none focus:ring-2 focus:ring-accent ${
      active ? "bg-accent text-white" : "bg-surface text-muted hover:text-foreground"
    }`;

  return (
    <main className="min-h-screen bg-transparent px-4 py-10 text-foreground sm:py-14">
      <div className="mx-auto max-w-4xl">
        <header className="mb-8 border-b border-border pb-6">
          <div className="relative z-30 mb-6">
            <div className="relative min-h-[150px] overflow-hidden rounded-[28px] border border-border bg-foreground shadow-hero sm:min-h-[180px]">
              <Image
                src="/tap-handles.jpg"
                alt="A row of beer taps behind a bar"
                fill
                priority
                sizes="(max-width: 1024px) 100vw, 896px"
                className="object-cover object-[center_42%]"
              />
            </div>
            <div className="absolute inset-x-0 top-0 flex justify-end p-4 sm:p-6">
              <SiteNav current="/schedule" />
            </div>
          </div>

          <p className="text-xs font-semibold uppercase tracking-[0.24em] text-accent">
            Unofficial and approximate
          </p>
          <h1 className="mt-2 font-display text-4xl font-semibold uppercase leading-none tracking-tight sm:text-6xl">
            Brewing Schedule
          </h1>
          <p className="mt-3 text-base leading-7 text-muted">
            Recommended and minimum days for each BrewPack. Total days is
            recommended brewing plus conditioning; the optional 1-day cold crash
            counts toward conditioning and adds no time. Condition at 35 to
            40°F.
          </p>
        </header>

        <div className="mb-4 space-y-3">
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search by name or style"
            aria-label="Search packs"
            className="w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent"
          />
          <div className="flex flex-wrap items-center gap-2">
            <div role="group" aria-label="Show" className="flex flex-wrap gap-2 rounded-2xl border border-border bg-field p-1.5">
              {FILTERS.map((f) => (
                <button key={f.id} type="button" aria-pressed={filter === f.id} onClick={() => setFilter(f.id)} className={chip(filter === f.id)}>
                  {f.label}
                </button>
              ))}
            </div>
            <label className="flex items-center gap-2 text-sm text-muted">
              Sort
              <select value={sort} onChange={(e) => setSort(e.target.value as Sort)} className="rounded-xl border border-border bg-surface px-3 py-2 text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-accent">
                {SORTS.map((s) => (
                  <option key={s.id} value={s.id}>{s.label}</option>
                ))}
              </select>
            </label>
            <div className="ml-auto flex flex-wrap gap-2">
              <a href="/schedule/pdf" className="rounded-xl bg-accent px-4 py-2 text-sm font-semibold text-white transition hover:bg-accent-hover focus:outline-none focus:ring-2 focus:ring-accent focus:ring-offset-2">
                Download PDF
              </a>
              <a href="/schedule/csv" download className={chip(false)}>
                Download CSV
              </a>
            </div>
          </div>
          <p className="text-sm text-muted" aria-live="polite">
            {shown.length} {shown.length === 1 ? "pack" : "packs"}. The PDF and CSV list every pack.
          </p>
        </div>

        <ul className="grid gap-4 sm:grid-cols-2">
          {shown.map((r) => (
            <li key={r.id} className="flex gap-4 rounded-2xl border border-border bg-surface p-3">
              <PackThumb packId={r.id} style={r.style} size={112} />
              <div className="min-w-0 flex-1">
                <h2 className="font-semibold leading-snug">{r.name}</h2>
                <p className="mt-0.5 text-xs text-muted">
                  {r.style} &middot; {r.abv.toFixed(1)}% ABV
                  {r.status !== "available" && (
                    <span className="ml-2 font-semibold uppercase text-stage-tap">{r.status}</span>
                  )}
                </p>
                <p className="mt-2 text-2xl font-semibold leading-none tabular-nums">
                  {r.totalDays}
                  <span className="ml-1 text-xs font-normal text-muted">days total</span>
                </p>
                <div className="mt-2 flex h-2 overflow-hidden rounded-full" role="img" aria-label={`Brew ${r.recommendedBrewDays} days, condition ${r.recommendedConditioningDays} days`}>
                  <span className="bg-stage-brew" style={{ flexGrow: r.recommendedBrewDays }} />
                  <span className="bg-stage-condition" style={{ flexGrow: r.recommendedConditioningDays }} />
                </div>
                <p className="mt-1 flex justify-between text-xs tabular-nums">
                  <span className="text-stage-brew">Brew {r.recommendedBrewDays}d</span>
                  <span className="text-stage-condition">Condition {r.recommendedConditioningDays}d</span>
                </p>
                <p className="mt-0.5 text-xs text-muted">
                  Minimum {r.minimumBrewDays} / {r.minimumConditioningDays} days
                </p>
              </div>
            </li>
          ))}
        </ul>
        {shown.length === 0 && <p className="py-6 text-center text-muted">No packs match.</p>}

        <div className="mt-8">
          <PinterNotice />
        </div>
      </div>
    </main>
  );
}
